    Bug 1957211 - Port bug 1954361: Allow to customize the mica backdrop we use for top levels. r=aleca

    Differential Revision: https://phabricator.services.mozilla.com/D243582

diff --git a/mail/themes/windows/mail/mailWindow1.css b/mail/themes/windows/mail/mailWindow1.css
index fd8aa6199ef..14d4fd008a6 100644
--- a/mail/themes/windows/mail/mailWindow1.css
+++ b/mail/themes/windows/mail/mailWindow1.css
@@ -65,6 +65,12 @@ treechildren::-moz-tree-row(dummy, selected, focus) {
   @media (-moz-windows-mica) and (-moz-windows-accent-color-in-titlebar: 0) {
     :root[customtitlebar]:not([lwtheme]) {
       background-color: transparent;
+
+      /* stylelint-disable-next-line media-query-no-invalid */
+      @media -moz-pref("widget.windows.mica.toplevel-backdrop", 2) {
+        /* For acrylic, do the same we do for popups to guarantee some contrast */
+        background-color: light-dark(rgba(255, 255, 255, 0.6), rgba(0, 0, 0, 0.6));
+      }
     }
   }
 }
